```python
import itertools

# Prime factorization of 240
prime_factors = [2, 2, 2, 2, 3, 5]

# Generate all divisors of 240
divisors = [1]
for p1 in prime_factors:
    for p2 in prime_factors:
        for p3 in prime_factors:
            for p4 in prime_factors:
                for p5 in prime_factors:
                    for p6 in prime_factors:
                        divisor = 1
                        for pf in [p1, p2, p3, p4, p5, p6]:
                            divisor *= pf
                        divisors.append(divisor)

divisors = sorted(divisors)

# Find all possible (a, b, c) combinations such that a * b * c = 240 and 1 < c < b < a
valid_combinations = []
for a in divisors:
    for b in divisors:
        if b < a:
            c = 240 // (a * b)
            if c in divisors and 1 < c < b:
                valid_combinations.append((a, b, c))

# Find the combination with the largest possible value of b
max_b = max(valid_combinations, key=lambda x: x[1])[1]

print(max_b)
